const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['home','工作空间','home'],['benches','企业工作台','grid'],['chat','Agent 会话','chat'],['tasks','任务中心','tasks'],['knowledge','知识与资料','folder'],['agents','Agent 中心','agents'],['plugins','插件与能力','plugin'],['admin','企业管理','users']];
const benches=[{name:'销售经营分析',desc:'从销售数据到经营洞察，让每一次决策都有据可依。',category:'销售运营',icon:'chart',color:'',owner:'销售运营部',tag:'企业专属',action:'sales'}, {name:'企业文档助手',desc:'沿用企业模板，完成合同初稿、通知与日常文书。',category:'行政协作',icon:'file',color:'blue',owner:'行政与人事',tag:'企业专属',action:'documents'}, {name:'品牌演示工坊',desc:'把想法变成演示。使用品牌模板制作可编辑 PPT。',category:'品牌营销',icon:'ppt',color:'gold',owner:'品牌与市场',tag:'PPT 能力',action:'ppt'}, {name:'企业知识问答',desc:'在制度、产品和项目资料中，找到有来源的答案。',category:'知识服务',icon:'book',color:'purple',owner:'全体成员',tag:'拟新增',action:'knowledge-chat'}, {name:'采购报价工作台',desc:'关联采购清单、产品目录与报价规则，生成报价草稿。',category:'销售运营',icon:'tasks',color:'gold',owner:'商务团队',tag:'拟新增',action:'quote'}, {name:'项目协作空间',desc:'汇集项目资料和待办，让团队共享同一份工作上下文。',category:'行政协作',icon:'users',color:'blue',owner:'项目管理部',tag:'拟新增',action:'project'}];
let state={page:'home',benchFilter:'全部',taskFilter:'全部',pluginFilter:'全部',setting:'模型与服务',folder:'全部资料',query:'',taskStage:'pending',chatTitle:'销售周报生成',chatPrompt:'分析本周销售数据，按企业模板生成一份销售周报，附上趋势和重点客户分析。',attachments:[],messages:[],busy:false,theme:'浅色',org:'远山科技',brand:'序 · 企业工作台',enabled:{'办公文件处理':true,'模板 PPT':true,'网页搜索':true,'图像生成':false,'智能体团队':false,'终端与命令':true,'语音输入':false,'自动化任务':false,'MCP 连接':true}};
try{const saved=JSON.parse(localStorage.getItem('enterprise-prototype-brand')||'null');if(saved){state.org=saved.org||state.org;state.brand=saved.brand||state.brand}}catch{}
const content=document.getElementById('content');
function applyBrand(){document.getElementById('org-name').textContent=state.org;document.getElementById('breadcrumb-org').textContent=state.org;document.getElementById('window-title').textContent=state.brand;document.title=state.brand+' — 桌面交互原型'}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
function renderNav(){document.getElementById('navigation').innerHTML=nav.map((n,i)=>`${i===0?'<div class="nav-label">工作</div>':''}${i===5?'<div class="nav-label">管理</div>':''}<button class="nav-item ${state.page===n[0]?'active':''}" data-page="${n[0]}" ${state.page===n[0]?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span>${n[0]==='tasks'&&state.taskStage==='pending'?'<span class="nav-count">1</span>':''}</button>`).join('')}
function navigate(page){if(!nav.some(n=>n[0]===page)&&page!=='settings')return;state.page=page;state.query='';location.hash=page;render();content.scrollTop=0;content.focus({preventScroll:true})}
function render(){renderNav();document.getElementById('breadcrumb').textContent=nav.find(n=>n[0]===state.page)?.[1]||'设置与连接';content.innerHTML=({home,benches:benchPage,chat,tasks,knowledge,agents,plugins,admin,settings}[state.page]||home)();if(state.safeDemo)content.insertAdjacentHTML('afterbegin',`<div class="intro-strip recovery-banner">${icon('shield')}安全模式演示：仅展示恢复状态，未禁用真实插件。 ${button('退出演示','safe-exit','text-button')}</div>`);hydrate();applyBrand();document.querySelector('.side-setting').classList.toggle('active',state.page==='settings');document.querySelectorAll('.tab').forEach(t=>t.setAttribute('aria-pressed',String(t.classList.contains('active'))))}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">ENTERPRISE WORKSPACE</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(text,action,cls='secondary',ic=''){return `<button type="button" class="${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`}
function badge(text){return `<span class="pill ${text==='拟新增'?'proposed':''}">${text}</span>`}
function benchCard(b){return `<article class="bench-card"><div class="card-top"><span class="app-icon ${b.color}">${icon(b.icon)}</span>${badge(b.tag)}</div><h3>${esc(b.name)}</h3><p>${esc(b.desc)}</p><div class="card-foot"><span>${esc(b.owner)}</span><button data-action="bench:${b.action}">进入工作台 ${icon('arrow')}</button></div></article>`}
function taskRows(){const rows=[['本周销售数据分析与周报',state.taskStage==='approved'?'已完成':state.taskStage==='rejected'?'已退回':'待确认','销售运营','刚刚','XLS',''],['品牌季度回顾演示文稿','已完成','品牌与市场','10:24','PPT','gold'],['整理产品 FAQ 与资料目录','已完成','知识服务','昨天','DOC','blue']];return rows.filter(r=>state.taskFilter==='全部'||r[1]===state.taskFilter).map(r=>`<tr class="clickable" data-action="task:${r[0]}" tabindex="0"><td><div class="task-name"><span class="file-icon ${r[5]}">${r[4]}</span>${r[0]}</div></td><td><span class="state ${r[1]==='待确认'?'pending':r[1]==='已退回'?'stopped':''}">${r[1]}</span></td><td class="muted">${r[2]}</td><td class="muted">${r[3]}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">没有符合条件的任务</td></tr>'}
function taskTable(){return `<table class="table"><thead><tr><th>任务名称</th><th>状态</th><th>工作台</th><th>最近更新</th></tr></thead><tbody>${taskRows()}</tbody></table>`}
function home(){return `${heading('让工作，井然有序。','下午好，林晓。你的企业资料、业务工具与 AI 助手，已在这里就位。',`<div class="date-block">${icon('calendar')}10 月 13 日，星期二</div>`)}<section class="hero"><div class="hero-copy"><div class="hero-label">${icon('spark')} YOUR WORK, CONNECTED.</div><h2>从一个想法，到一份完成的工作。</h2><p>交给企业助手，让它理解资料、调用工具，并带回你需要的结果。</p><form id="hero-form" class="hero-command">${icon('spark')}<input id="hero-prompt" aria-label="描述任务" placeholder="例如：分析本周销售数据，生成一份经营周报"><button type="submit">开始任务 ↗</button></form></div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="art-card"><i></i><i></i><i></i></div><div class="art-mini">${icon('check')}让每一步，都有结果</div></div></section><div class="section-header"><h2>我的工作台 <small>为你的业务而准备</small></h2><button class="text-button" data-page="benches">全部工作台 ${icon('arrow')}</button></div><div class="bench-grid">${benches.slice(0,4).map(benchCard).join('')}</div><div class="lower-grid"><section><div class="section-header"><h2>最近任务</h2><button class="text-button" data-page="tasks">查看全部 →</button></div><div class="panel">${taskTable()}</div></section><section><div class="section-header"><h2>需要你确认 <small>${(state.taskStage==='pending'?1:0)+(state.knowledgePublished?0:1)} 项待办</small></h2>${icon('shield')}</div><div class="panel"><div class="approval-item"><div class="approval-line"><h3>${state.taskStage==='approved'?'销售周报已交付':'销售周报 · 文件交付'}</h3><span class="state ${state.taskStage==='pending'?'pending':''}">${state.taskStage==='pending'?'待确认':'已处理'}</span></div><p>周报草稿已准备好，请检查分析口径后保存到工作区。</p><button class="text-button" data-action="bench:sales">查看详情 →</button></div><div class="approval-item"><div class="approval-line"><h3>产品手册 · 资料更新</h3>${badge(state.knowledgePublished?'已发布（演示）':'拟新增')}</div><p>${state.knowledgePublished?'已完成演示确认，没有发布真实资料。':'知识管理员提交了新版产品手册，等待发布确认。'}</p><button class="text-button" data-action="knowledge-review">查看资料 →</button></div><div class="news-line">${icon('shield')}关键操作由你确认，执行过程有迹可循。</div></div></section></div>`}
function benchPage(){const list=benches.filter(b=>(state.benchFilter==='全部'||b.category===state.benchFilter)&&(b.name+b.desc).includes(state.query));return `${heading('企业工作台','按业务组织能力，让每个岗位都有自己的工作空间。',button('工作台市场','market')+button('创建工作台','create-bench','primary','plus'))}<div class="toolbar"><div class="tabs">${['全部','销售运营','行政协作','品牌营销','知识服务'].map(t=>`<button class="tab ${state.benchFilter===t?'active':''}" data-bench-filter="${t}">${t}</button>`).join('')}</div><label class="input-wrap">${icon('search')}<input id="bench-search" placeholder="搜索工作台" aria-label="搜索工作台" value="${esc(state.query)}"></label></div><div class="bench-grid full-grid" id="bench-results">${list.map(benchCard).join('')||'<div class="empty">没有找到工作台</div>'}</div><div class="intro-strip">${icon('plugin')}原有社区工作台与自建工作台继续保留；企业工作台在其基础上增加品牌、资料、模板和岗位入口。</div>`}
function chat(){if(state.scenario&&state.scenario!=='sales')return genericChat();const ready=state.taskStage==='approved';return `${heading(state.chatTitle,'销售运营 / 本地工作区 / 会话内容为交互演示',button('会话历史','history')+button('工作区','workspace','secondary','folder'))}<div class="chat-layout"><section class="chat-main"><div class="chat-head"><div><h3>销售分析助手 <span class="pill">企业 Preset</span></h3><small>DeepSeek · 需在正式应用配置模型</small></div>${button('更多能力','capabilities','text-button')}</div><div class="chat-transcript"><div class="message"><span class="avatar">林</span><div class="message-body"><strong>你</strong><p>${esc(state.chatPrompt)}</p><span class="file-chip">${icon('file')}销售明细_本周.xlsx</span><span class="file-chip">${icon('file')}企业周报模板.docx</span></div></div><div class="message"><span class="avatar agent-avatar">序</span><div class="message-body"><strong>销售分析助手 <span class="muted">· 演示结果</span></strong><p>我已按企业口径整理销售数据。以下是本次工作的执行记录与交付草稿。</p><div class="steps"><div class="step">${icon('check')}读取 2 份工作区资料，校验字段与统计周期</div><div class="step">${icon('check')}汇总销售额、区域趋势与重点客户</div><div class="step">${icon('check')}应用企业模板，生成周报草稿</div></div>${ready?`<div class="intro-strip">${icon('check')}已确认交付。可在右侧查看报告或下载演示文本。</div>`:state.taskStage==='rejected'?'<div class="intro-strip">已退回草稿。你可以在下方补充修改要求。</div>':`<div class="approval-box"><h3>等待你的确认</h3><p>拟保存：销售运营 / 交付物 / 本周销售周报.docx<br>操作范围：创建新文件；不会覆盖原始销售表。</p>${button('确认并生成交付物','approve','primary','check')} ${button('退回修改','reject')}</div>`}</div></div>${state.messages.map(m=>`<div class="message"><span class="avatar">林</span><div class="message-body"><strong>你</strong><p>${esc(m)}</p><p class="muted">${state.busy?'正在模拟整理任务…':'演示任务已记录。原型不会调用模型或执行真实操作。'}</p></div></div>`).join('')}</div><form id="chat-form" class="composer"><div class="attachment-list">${state.attachments.map(esc).join(' · ')}</div><textarea id="chat-input" aria-label="输入任务" placeholder="继续补充要求，或描述一项新任务…"></textarea><div class="composer-tools">${button('附件','attach','chip-button','plus')}${button('PPT 模式','ppt','chip-button','ppt')}${button('选择模型','model','chip-button')}${button('工具','capabilities','chip-button','plugin')}${button('语音','voice','chip-button')}${state.busy?button('停止','stop','primary send','stop'):'<button class="primary send" type="submit">发送 ↑</button>'}</div></form></section><aside class="inspector"><div class="panel"><div class="panel-head"><h3>任务上下文</h3>${icon('folder')}</div><div class="inspector-body"><div class="inspector-row"><span>工作区</span><button class="text-button" data-action="workspace">销售运营 ↗</button></div><div class="inspector-row"><span>参考资料</span><span>2 份文件</span></div><div class="inspector-row"><span>执行权限</span><span>关键操作需确认</span></div><div class="inspector-row"><span>任务状态</span><span class="state ${ready?'':'pending'}">${ready?'已完成':state.taskStage==='rejected'?'已退回':'待确认'}</span></div><p>资料保存在工作区。正式应用调用云模型时，参与推理的内容会发送到模型服务。</p></div></div><div class="panel"><div class="panel-head"><h3>交付物预览</h3><span>01</span></div><button class="preview-paper" data-action="preview" style="text-align:left;width:calc(100% - 30px)"><div class="paper-eyebrow">YUANSHAN / WEEKLY REPORT</div><h4>本周销售经营周报</h4><small style="font-size:8px">2026.10.05 — 2026.10.11 · 演示</small><div class="paper-rule"></div><div class="paper-lines"><i></i><i style="width:80%"></i></div><div class="mini-chart"><i style="height:40%"></i><i style="height:64%"></i><i style="height:55%"></i><i style="height:83%"></i><i style="height:100%"></i></div></button><div style="padding:0 15px 15px;display:flex;gap:8px">${button('预览','preview','secondary','file')}${button('下载演示文本','download','text-button','download')}</div></div></aside></div>`}
function tasks(){return `${heading('任务中心','每一次委托，都有过程、有结果、有记录。',button('新建任务','new-task','primary','plus'))}<div class="summary-grid"><div class="metric"><span>全部任务</span><strong>3 <small>项演示任务</small></strong></div><div class="metric"><span>等待我的确认</span><strong>${state.taskStage==='pending'?'1':'0'} <small>项文件交付</small></strong></div><div class="metric"><span>已完成</span><strong>${state.taskStage==='approved'?'3':'2'} <small>项任务</small></strong></div></div><div class="toolbar"><div class="tabs">${['全部','待确认','已完成','已退回'].map(t=>`<button class="tab ${state.taskFilter===t?'active':''}" data-task-filter="${t}">${t}</button>`).join('')}</div>${button('审批记录','approval-history','secondary','shield')+button('自动化任务','automation','secondary','clock')}</div><div class="panel">${taskTable()}</div>`}
const files=[['产品手册 2026 · 秋季版','PDF','产品资料','2.4 MB','今天 09:40'],['本周销售明细','XLSX','销售数据','186 KB','今天 09:15'],['企业周报标准模板','DOCX','企业模板','52 KB','昨天 16:20'],['远山科技品牌演示模板','PPTX','企业模板','4.8 MB','10-10 14:30'],['员工差旅与报销制度','PDF','企业制度','890 KB','10-09 11:00']];
const pluginList=[['办公文件处理','DOCX / XLSX / PDF 文件处理与预览','file','内置'],['模板 PPT','16 套模板的选择与可编辑 PPTX 交付入口','ppt','内置'],['网页搜索','保留原有网页检索与抓取能力','search','内置'],['图像生成','按服务配置提供图像生成能力','spark','扩展'],['智能体团队','协作成员、共享任务与团队工具','users','实验性'],['终端与命令','保留原有终端和命令执行配置','tasks','内置'],['语音输入','本地语音转写，正式使用需准备依赖','chat','实验性'],['自动化任务','在会话中按计划执行任务','clock','实验性'],['MCP 连接','对接企业系统和外部工具服务','link','扩展']];
function plugins(){return `${heading('插件与能力','企业入口更简洁，底层能力依旧完整。',button('社区插件市场','market')+button('添加能力','add-plugin','primary','plus'))}<div class="toolbar"><div class="tabs">${['全部','内置','扩展','实验性'].map(t=>`<button class="tab ${state.pluginFilter===t?'active':''}" data-plugin-filter="${t}">${t}</button>`).join('')}</div><small>${Object.values(state.enabled).filter(Boolean).length} 项演示启用 · 不代表真实安装</small></div><div class="bench-grid full-grid">${pluginList.filter(p=>state.pluginFilter==='全部'||state.pluginFilter===p[3]).map(p=>`<article class="bench-card"><div class="card-top"><span class="app-icon">${icon(p[2])}</span><button class="switch ${state.enabled[p[0]]?'on':''}" data-toggle="${p[0]}" role="switch" aria-label="${p[0]}" aria-checked="${state.enabled[p[0]]}"></button></div><h3>${p[0]}</h3><p>${p[1]}</p><div class="card-foot">${badge(p[3])}<button data-action="plugin:${p[0]}">配置 →</button></div></article>`).join('')}</div>`}
function admin(){return `${heading('企业管理','统一品牌与使用规则，为团队建立清晰的协作边界。',badge('拟新增'))}<div class="intro-strip">${icon('shield')}以下是企业层设计，不代表当前 DSH Desktop 已实现账号、多租户、服务端权限或审计。</div><div class="lower-grid"><div class="panel settings-panel"><h2>品牌与组织</h2><p>在原有桌面客户端外增加企业身份，保留底层能力与来源说明。</p><form id="brand-form"><div class="setting-row"><div><h3>企业名称</h3><p>显示在工作空间与侧边栏</p></div><input name="org" aria-label="企业名称" maxlength="20" value="${esc(state.org)}" required></div><div class="setting-row"><div><h3>应用名称</h3><p>显示在桌面标题栏</p></div><input name="brand" aria-label="应用名称" maxlength="30" value="${esc(state.brand)}" required></div><div class="setting-row"><div><h3>品牌主色</h3><p>V0.1 采用远山绿与浅灰白</p></div><span class="app-icon" style="background:#245c48;color:white">序</span></div><div class="modal-actions"><button type="submit" class="primary">保存演示设置</button></div></form></div><div class="panel settings-panel"><h2>成员与角色</h2><p>先明确权限设计，再确定企业服务端方案。 ${button('查看权限矩阵','permissions','text-button')}</p>${[['林晓','管理员','管理品牌、成员与策略'],['陈安','业务负责人','管理本部门工作台和模板'],['许宁','成员','执行授权任务和访问资料']].map(m=>`<div class="setting-row"><div><h3>${m[0]} · ${m[1]}</h3><p>${m[2]}</p></div>${button('查看','role:'+m[1],'text-button')}</div>`).join('')}${button('邀请成员','invite','text-button','plus')}<p style="margin-top:14px">本次已保存 ${state.memberDrafts?.length||0} 份邀请草稿，未发送。</p></div></div><div class="panel settings-panel" style="margin-top:22px"><h2>数据与操作治理</h2><p style="margin-top:8px">当前演示策略：${state.externalPolicy==='deny'?'禁止对外发送':'对外发送前确认'} · 文件覆盖需确认</p><div class="setting-row"><div><h3>关键操作确认</h3><p>文件覆盖、系统写入与对外发送遵循明确的操作范围。UI 显隐不代替后端权限校验。</p></div>${button('查看策略','policy')}</div><div class="setting-row"><div><h3>审计与用量</h3><p>拟记录操作者、工作台、工具、确认结果与模型用量；记录范围需与企业约定。</p></div>${button('查看示例','audit')}</div></div>`}
const settingNames=['模型与服务','本地工作区','主题与显示','手机连接','更新与恢复','隐私与数据'];
function settings(){let inner='';switch(state.setting){case '模型与服务':inner=`<h2>模型与服务</h2><p>保留多模型配置。企业可预设服务，成员在授权范围内选择。</p>${[['DeepSeek','D','官方模型服务'],['Anthropic','A','第三方模型服务'],['自定义服务','+','企业网关 / 自托管端点']].map(m=>`<div class="setting-row"><div class="model-heading"><span class="model-logo">${m[1]}</span><div><h3>${m[0]}</h3><p>${m[2]} · 未连接（原型）</p></div></div>${button('配置','model')}</div>`).join('')}`;break;case '本地工作区':inner=`<h2>本地工作区</h2><p>沿用桌面端的文件夹选择与工作区管理。</p>${['销售运营','品牌与市场'].map(x=>`<div class="setting-row"><div><h3>${x}</h3><p>本地文件夹 · 演示路径未绑定</p></div>${button('管理','workspace')}</div>`).join('')}${button('添加工作区','workspace','text-button','plus')}`;break;case '主题与显示':inner=`<h2>主题与显示</h2><p>保留主题、缩放、窗口与桌面菜单。当前原型展示企业浅色主题。</p><div class="setting-row"><div><h3>界面密度</h3><p>切换标准与紧凑布局</p></div>${button('切换密度','maximize')}</div><div class="setting-row"><div><h3>主题扩展</h3><p>正式产品继续保留原有主题切换能力</p></div>${button('查看说明','theme')}</div>`;break;case '手机连接':inner=`<h2>手机连接</h2><p>保留局域网配对与临时公网连接。此原型不会开启网络隧道。</p><div class="setting-row"><div><h3>局域网配对</h3><p>正式应用使用短时二维码建立连接</p></div>${button('查看配对流程','phone','primary','phone')}</div><div class="setting-row"><div><h3>临时公网连接</h3><p>企业策略可限制使用，入口继续保留</p></div>${button('连接设置','phone')}</div>`;break;case '更新与恢复':inner=`<h2>更新与恢复</h2><p>应用数据与安装目录分离，延续原有更新和恢复机制。</p>${[['应用更新','由用户决定下载、安装与重启','updates'],['安全模式','临时屏蔽第三方插件，保留恢复入口','safe'],['运行日志','提供诊断信息并避免泄露凭据','logs'],['重新启动服务','重启桌面内置 Agent 服务','restart']].map(x=>`<div class="setting-row"><div><h3>${x[0]}</h3><p>${x[1]}</p></div>${button('查看','system:'+x[2])}</div>`).join('')}`;break;default:inner=`<h2>隐私与数据</h2><p>本地保存不等于离线推理。正式产品需清楚展示各项联网行为。</p>${[['模型请求','调用云模型时，相关文本与附件内容可能发送到服务商。'],['产品统计与反馈','沿用并明确配置产品埋点和反馈遥测，不能用“本地优先”掩盖联网。'],['会话与工作区','沿用现有本地会话和工作区数据；企业同步为独立设计项。']].map(x=>`<div class="setting-row"><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}${button('查看原型边界','help','text-button')}`}
return `${heading('设置与连接','熟悉的桌面能力，始终触手可及。')}<div class="settings-layout"><aside class="settings-nav">${settingNames.map(n=>`<button class="${state.setting===n?'active':''}" data-setting="${n}">${n}</button>`).join('')}</aside><div class="panel settings-panel">${inner}</div></div>`}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('toast-visible'),3000)}
function modal(title,html){document.getElementById('modal-title').textContent=title;document.getElementById('modal-body').innerHTML=html;const d=document.getElementById('modal');if(!d.open)d.showModal();hydrate();document.querySelectorAll('#modal-body label').forEach((label,i)=>{const field=label.nextElementSibling;if(!label.htmlFor&&field?.matches('input,select,textarea')){field.id ||= 'modal-field-'+i;label.htmlFor=field.id}})}
function closeModal(){document.getElementById('modal').close()}
function info(title,text){modal(title,`<p>${text}</p><div class="modal-actions">${button('知道了','dismiss','primary')}</div>`)}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob(['\ufeff'+text],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('已下载原型演示文件')}
function preview(){modal('本周销售经营周报 · 演示预览',`<div class="report-preview"><div class="paper-eyebrow">${esc(state.org)} / WEEKLY REPORT</div><h2>本周销售经营周报</h2><p>统计周期：2026.10.05 — 2026.10.11<br>状态：${state.taskStage==='approved'?'已确认':'待确认草稿'} · 以下数据为虚构示例</p><table class="table"><thead><tr><th>指标</th><th>本周</th><th>环比</th></tr></thead><tbody><tr><td>销售额</td><td>¥ 286,400</td><td>+12.8%</td></tr><tr><td>成交订单</td><td>48</td><td>+6</td></tr><tr><td>新增客户</td><td>12</td><td>+3</td></tr></tbody></table><p style="margin-top:20px">经营摘要：华东区域贡献主要增量，重点客户续单表现稳定。建议下周重点跟进三个处于报价阶段的客户。</p><small>参考资料：销售明细_本周.xlsx；企业周报模板.docx。原型未解析真实附件。</small></div><div class="modal-actions">${button('下载演示文本','download','primary','download')}</div>`)}
function action(a){if(a==='help'){modal('原型说明与演示重置',`<p>本原型展示企业 PC 客户端的页面与交互。数据为虚构样本，不调用模型、不安装插件、不发送消息。</p><p>Alt+N 新建任务；Ctrl+K 搜索；Esc 关闭弹窗。只有企业名称和应用名尝试保存在当前浏览器，其他状态刷新后重置。</p><div class="modal-actions">${button('重置销售周报','reset-demo')}${button('恢复初始品牌','reset-brand')}${button('关闭','dismiss','primary')}</div>`);return}if(a==='reset-brand'){state.org='远山科技';state.brand='序 · 企业工作台';try{localStorage.removeItem('enterprise-prototype-brand')}catch{}applyBrand();if(state.page==='admin')render();toast('已恢复初始品牌');return}if(desktopAction(a))return;if(enterpriseAction(a))return;if(pluginAction(a))return;if(agentAction(a))return;if(knowledgeAction(a))return;if(taskAction(a))return;if(scenarioAction(a))return;if(a==='dismiss')return closeModal();if(a==='search'){modal('搜索工作空间',`<input id="global-search" placeholder="搜索工作台、任务、资料…" aria-label="搜索工作空间"><div id="search-results"></div>`);search('');return}if(a.startsWith('bench:')){state.chatTitle=({sales:'销售周报生成',documents:'企业文档撰写',ppt:'品牌演示制作','knowledge-chat':'企业知识问答',quote:'采购报价草稿',project:'项目资料整理'})[a.split(':')[1]]||'新任务';state.chatPrompt=state.chatTitle==='销售周报生成'?'分析本周销售数据，按企业模板生成一份销售周报，附上趋势和重点客户分析。':`我想使用${state.chatTitle}工作台，请演示一项企业任务。`;navigate('chat');if(a==='bench:ppt')action('ppt');return}if(a.startsWith('task:')){if(a.includes('周报'))return action('bench:sales');return info('任务记录',`${esc(a.slice(5))}<br>状态：已完成（演示）。原有会话历史与任务记录继续保留。`)}
if(a==='approve'){state.taskStage='approved';render();toast('已确认，演示交付物已就绪');return}if(a==='reject'){state.taskStage='rejected';render();toast('草稿已退回，可补充修改要求');return}if(a==='preview')return preview();if(a==='download')return download('本周销售周报_原型演示.txt','企业工作台 · 原型演示\n本周销售经营周报\n以下为虚构示例，不来源于真实文件。\n销售额：286,400 元；成交订单：48；新增客户：12。\n本文件为文本演示，不是 DOCX 或真实 Agent 产出。');if(a==='attach'||a==='import-preset'){document.getElementById('file-picker').accept=a==='import-preset'?'.dshpreset':'';document.getElementById('file-picker').dataset.kind=a;document.getElementById('file-picker').click();return}if(a==='new-task'){navigate('chat');return}if(a==='stop'){state.busy=false;clearTimeout(state.timer);render();toast('演示执行已停止');return}if(a==='maximize'){document.body.classList.toggle('compact');toast('已切换界面密度');return}if(a==='minimize'||a==='close'){info('桌面窗口控制','这是在浏览器中预览的 PC 桌面原型。正式 Electron 应用将调用原生最小化、最大化和关闭行为。');return}
if(a==='model'){modal('配置模型服务',`<p>原型仅展示配置字段，请勿输入真实密钥。正式产品沿用原有凭据管理。</p><label>模型提供方</label><select><option>DeepSeek</option><option>Anthropic</option><option>企业网关 / 自托管服务</option></select><label>服务地址（示例）</label><input placeholder="https://your-model-endpoint.example"><label>API Key</label><input type="password" disabled placeholder="原型不接收真实凭据"><div class="modal-actions">${button('取消','dismiss')}${button('保存演示配置','model-save','primary')}</div>`);return}if(a==='model-save'){closeModal();toast('演示配置已确认，未建立真实模型连接');return}
if(a==='ppt'){modal('选择企业演示模板',`<p>保留原有 16 套 PPT 模板与可编辑 PPTX 交付能力；下方展示 3 个原型样式入口。</p><div class="bench-grid" style="grid-template-columns:repeat(3,1fr)">${[['远山 · 品牌绿','#e5eddf'],['商务 · 深海蓝','#e4eaf3'],['年度 · 暖砂金','#f1e9d8']].map(t=>`<button data-action="template:${t[0]}" class="bench-card" style="min-height:135px;background:${t[1]};text-align:left"><div style="height:55px;font-size:28px;font-family:serif">Aa</div><strong>${t[0]}</strong><small style="display:block;margin-top:12px">选择模板 →</small></button>`).join('')}</div>`);return}if(a.startsWith('template:')){closeModal();toast('已选择 '+a.slice(9)+'，正式应用将进入原有 PPT 流程');return}
if(a==='workspace'){modal('本地工作区',`<p>正式桌面端继续使用原生文件夹选择器。原型不读取磁盘目录。</p><div class="setting-row"><div><h3>销售运营</h3><p>资料 / 模板 / 交付物</p></div>${badge('演示')}</div><div class="setting-row"><div><h3>品牌与市场</h3><p>素材 / 演示 / 项目</p></div>${badge('演示')}</div><div class="modal-actions">${button('选择文件演示','attach','primary','folder')}</div>`);return}
if(a==='create-bench'||a==='create-agent'){modal(a==='create-bench'?'创建企业工作台':'创建企业助手',`<p>演示企业配置流程，不会安装插件或创建真实 Agent。</p><form id="create-form" data-kind="${a}"><label>名称</label><input name="name" maxlength="24" placeholder="例如：客户服务工作台" required><label>业务说明</label><textarea name="desc" rows="3" placeholder="这个工作台帮助员工完成什么工作？" required></textarea><label>访问范围</label><select><option>仅自己</option><option>本部门（企业能力设计）</option><option>全体成员（企业能力设计）</option></select><div class="modal-actions"><button type="submit" class="primary">创建演示${a==='create-bench'?'工作台':'配置'}</button></div></form>`);return}
if(a.startsWith('agent:')){modal(a.slice(6)+' · 配置',`<p>使用原有 Preset 组合模型、提示词与工具。</p><div class="permissions">默认模型：DeepSeek（未连接）<br>Skills：文档处理、数据分析<br>MCP：企业数据服务（拟接入）<br>默认权限：关键操作需确认<br>数据范围：当前授权工作区</div><div class="modal-actions">${button('导出配置示例','export-preset','primary')}</div>`);return}if(a==='export-preset'){download('企业助手_配置示例.json',JSON.stringify({prototype:true,name:'企业助手',note:'界面设计示例，不是可导入的 dshpreset 文件',tools:['office','search'],approval:'关键操作需确认'},null,2),'application/json');return}
if(a.startsWith('file:')||a==='knowledge-review'){modal(a==='knowledge-review'?'产品手册 · 发布确认':a.slice(5),`<p>资料来源：企业演示数据<br>所属范围：当前企业（拟新增权限）<br>版本：V1.2 · 待审核</p><div class="intro-strip">共享检索、版本发布与权限由后续企业服务设计承载。原型不会上传文件。</div><div class="modal-actions">${button('关闭','dismiss')}${button('模拟确认发布','publish-demo','primary')}</div>`);return}if(a==='publish-demo'){state.knowledgePublished=true;closeModal();render();toast('已演示确认发布，未更新任何真实资料');return}
if(a==='capabilities'){navigate('plugins');return}if(a==='organization'){navigate('admin');return}if(a==='history'){navigate('tasks');return}if(a==='automation'){navigate('plugins');state.pluginFilter='实验性';render();return}
const explanations={help:['关于本次原型','这是企业桌面端改造设计 V0.1。所有数据、状态和业务结果都是演示。支持页面切换、任务确认、模板选择、资料选择、搜索与品牌设置；不会调用模型、发送消息、安装插件或修改企业系统。<br><br>企业品牌设置尝试保存在当前浏览器本地，其余演示状态刷新后重置。'],market:['工作台与插件市场','正式产品保留原有市场浏览、搜索、安装、更新、卸载与主题功能。企业层可增加推荐清单和安装策略。<br><br>此处为入口设计，不会实际联网安装。'],phone:['连接手机','正式应用：选择局域网或临时公网 → 显示短时配对二维码 → 手机确认配对 → 继续会话 → 随时断开。<br><br>原型不生成真实二维码、不开放端口、不启动公网隧道。'],voice:['语音输入','保留原有本地语音转写入口。正式应用按原流程准备运行依赖与麦克风权限；原型不请求麦克风。'],theme:['主题与显示','保留原有主题与缩放入口。当前展示企业浅色主题；深色主题与品牌主题扩展留待后续设计。'],invite:['邀请成员 · 拟新增','拟支持管理员邀请成员、分配部门和角色。具体账号与服务端方案尚未确定；原型不会发送邀请。'],policy:['企业操作策略 · 拟新增','成员只能访问已授权资料和工具；覆盖文件、外发消息和写入企业系统须按规则确认。正式实现需要后端权限校验，不能只隐藏按钮。'],audit:['审计记录示例 · 拟新增','10:30　林晓　销售周报　读取授权资料　成功<br>10:31　销售分析助手　生成报告草稿　等待确认<br>10:32　林晓　批准文件交付　演示记录<br><br>正式审计字段、存储、脱敏和保留周期待设计。'],'add-plugin':['添加能力','保留原有插件安装、Skills 与 MCP 配置能力。企业系统接入需要独立的连接配置和权限。原型不安装依赖。']};
if(a.startsWith('system:')){const names={updates:'检查应用更新',safe:'安全模式',logs:'运行日志',restart:'重新启动服务'};info(names[a.slice(7)],'该入口在正式应用中连接原有桌面功能。原型不会检查更新、重启服务、删除插件或访问真实日志。');return}if(a.startsWith('role:')){info(a.slice(5)+' · 权限设计','管理员维护组织策略；业务负责人维护本部门工作台与模板；成员执行授权任务。实际权限必须由服务端或受信任宿主校验。');return}if(a.startsWith('plugin:')){info(a.slice(7)+' · 配置入口','正式产品复用原有插件配置页面，保留详细参数。企业层只提供默认配置与策略，不删减原有功能。原型开关只用于展示交互。');return}if(explanations[a])info(...explanations[a]);}
function search(q){const results=[...nav.map(n=>[n[1],n[0],'页面']),...benches.map(b=>[b.name,'bench:'+b.action,'工作台']),...files.map(f=>[f[0],'file:'+f[0],'资料']),['销售周报生成','bench:sales','任务'],['品牌季度回顾演示文稿','task:品牌季度回顾演示文稿','任务']].filter(r=>r[0].toLowerCase().includes(q.toLowerCase()));document.getElementById('search-results').innerHTML=results.map(r=>`<button class="search-result" ${r[1].includes(':')?`data-search-action="${esc(r[1])}"`:`data-search-page="${r[1]}"`}>${esc(r[0])}<small>${r[2]} ↗</small></button>`).join('')||'<div class="empty">没有找到匹配内容</div>'}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-action]');if(!b)return;if(b.dataset.page)return navigate(b.dataset.page);if(b.dataset.searchPage){closeModal();return navigate(b.dataset.searchPage)}if(b.dataset.searchAction){closeModal();return action(b.dataset.searchAction)}if(b.dataset.action)return action(b.dataset.action);if(b.dataset.benchFilter){state.benchFilter=b.dataset.benchFilter;render()}if(b.dataset.taskFilter){state.taskFilter=b.dataset.taskFilter;render()}if(b.dataset.pluginFilter){state.pluginFilter=b.dataset.pluginFilter;render()}if(b.dataset.folder){state.folder=b.dataset.folder;render()}if(b.dataset.setting){state.setting=b.dataset.setting;render()}if(b.dataset.toggle){requestPluginToggle(b.dataset.toggle)}});
document.addEventListener('input',e=>{if(e.target.id==='global-search')search(e.target.value);if(e.target.id==='bench-search'){state.query=e.target.value;document.getElementById('bench-results').innerHTML=benches.filter(b=>(state.benchFilter==='全部'||b.category===state.benchFilter)&&(b.name+b.desc).includes(state.query)).map(benchCard).join('')||'<div class="empty">没有找到工作台</div>'}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='hero-form'){state.scenario='general';const q=document.getElementById('hero-prompt').value.trim();state.chatPrompt=q||state.chatPrompt;state.chatTitle=q?'新的企业任务':'销售周报生成';navigate('chat')}if(e.target.id==='chat-form'){const q=document.getElementById('chat-input').value.trim();if(!q)return toast('请先描述任务');if(state.busy)return;state.messages.push(q);state.busy=true;render();state.timer=setTimeout(()=>{state.busy=false;if(state.page==='chat')render();toast('演示执行完成，未调用模型')},1800)}if(e.target.id==='brand-form'){const f=new FormData(e.target);state.org=String(f.get('org')).trim();state.brand=String(f.get('brand')).trim();if(!state.org||!state.brand)return toast('请填写名称');try{localStorage.setItem('enterprise-prototype-brand',JSON.stringify({org:state.org,brand:state.brand}));toast('品牌设置已保存在本浏览器')}catch{toast('品牌设置已应用，本浏览器未允许持久保存')}applyBrand()}if(e.target.id==='create-form'){const f=new FormData(e.target);const name=String(f.get('name')).trim(),desc=String(f.get('desc')).trim();if(!name||!desc)return toast('请完整填写名称和说明');if(e.target.dataset.kind==='create-bench'){benches.push({name,desc,category:'行政协作',icon:'grid',color:'',owner:'仅自己',tag:'拟新增',action:'custom-'+benches.length});state.benchFilter='全部';closeModal();navigate('benches');toast('演示工作台已创建')}else{agentDefinitions.push({name,role:desc,skills:'自定义工具组合',scope:'仅自己',prompt:desc});closeModal();navigate('agents');toast('演示助手已创建，未创建真实 Preset 文件')}}});
document.getElementById('file-picker').addEventListener('change',e=>{const selected=Array.from(e.target.files||[]);if(!selected.length)return;state.attachments=selected.map(f=>f.name);if(state.page==='knowledge'&&e.target.dataset.kind!=='import-preset'){selected.forEach(f=>files.push([f.name,(f.name.split('.').pop()||'FILE').toUpperCase().slice(0,5),state.folder==='全部资料'?'导入记录':state.folder,(f.size/1024).toFixed(1)+' KB','刚刚 · 仅文件名']));render()}if(e.target.dataset.kind==='import-preset')info('Preset 导入预检',`已选择 ${esc(selected[0].name)}。正式应用需校验包内容、名称冲突与信任来源；原型只读取文件名，不解析或执行配置。`);else{if(state.page==='chat')render();info('资料选择结果',`已选择 ${state.attachments.map(esc).join('、')}。<br>本次仅展示文件名，没有上传、解析或加入知识库。`)}e.target.value=''});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('search')}if(e.key==='Enter'&&e.target.matches('tr[data-action]'))action(e.target.dataset.action)});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==state.page&&(nav.some(n=>n[0]===p)||p==='settings')){state.page=p;render()}});
document.addEventListener('DOMContentLoaded',()=>{state.page=nav.some(n=>n[0]===location.hash.slice(1))||location.hash==='#settings'?location.hash.slice(1):'home';render()});

// Round 2: keyboard navigation and useful desktop shortcuts.
document.addEventListener('keydown',e=>{
 if(e.altKey&&e.key.toLowerCase()==='n'){e.preventDefault();action('new-task')}
 const d=document.getElementById('modal');
 if(d.open&&document.getElementById('global-search')){
  const results=[...d.querySelectorAll('.search-result')];const i=results.indexOf(document.activeElement);
  if(e.key==='ArrowDown'&&results.length){e.preventDefault();results[Math.min(i+1,results.length-1)].focus()}
  if(e.key==='ArrowUp'&&results.length){e.preventDefault();if(i<=0)document.getElementById('global-search').focus();else results[i-1].focus()}
 }
});
// Round 3: every workbench retains its own context; new tasks start empty.
const scenarioDefinitions={sales:{title:'销售经营分析',assistant:'销售分析助手',workspace:'销售运营',prompt:'分析本周销售数据，按企业模板生成销售周报。',steps:['选择销售表与统计口径','分析趋势与重点客户','预览并确认交付'],output:'经营周报 · DOCX'},documents:{title:'企业文档助手',assistant:'文档撰写助手',workspace:'行政协作',prompt:'按企业通知模板，起草下周全员培训通知。',steps:['选择企业文档模板','补充受众与事实信息','校对后导出草稿'],output:'文档草稿 · DOCX'},ppt:{title:'品牌演示工坊',assistant:'演示制作助手',workspace:'品牌与市场',prompt:'基于季度总结，制作一份 10 页的品牌演示。',steps:['选择 PPT 模板','确认结构与素材','预览并交付可编辑文件'],output:'演示文稿 · PPTX'},'knowledge-chat':{title:'企业知识问答',assistant:'企业知识助手',workspace:'企业资料',prompt:'查找差旅报销标准，并标明依据的制度和章节。',steps:['限定资料范围','检索并定位引用','给出有来源的回答'],output:'回答与引用 · 拟新增'},quote:{title:'采购报价工作台',assistant:'商务报价助手',workspace:'销售运营',prompt:'根据采购清单和产品目录，生成待审核的报价草稿。',steps:['匹配产品与数量','用业务规则计算价格','审核后交付报价'],output:'报价草稿 · XLSX'},project:{title:'项目协作空间',assistant:'项目助理',workspace:'项目资料',prompt:'整理项目进度，列出下周待办和需要确认的风险。',steps:['汇总项目资料','整理状态与风险','形成项目周报'],output:'项目周报 · DOCX'}};
function scenarioAction(a){
 if(a==='new-task'){clearTimeout(state.timer);state.busy=false;state.activeAgent=null;state.scenario='general';state.chatTitle='新的企业任务';state.chatPrompt='';state.messages=[];state.attachments=[];navigate('chat');return true}
 if(a.startsWith('bench:')){const key=a.slice(6);const b=benches.find(x=>x.action===key);const d=scenarioDefinitions[key]||{...scenarioDefinitions.project,title:b?.name||'企业工作台'};modal(d.title,`<p>${esc(b?.desc||'从业务目标出发，组合资料、工具与企业模板。')}</p><div class="workflow-steps">${d.steps.map((x,i)=>`<div><span>${i+1}</span><strong>${x}</strong></div>`).join('')}</div><div class="workbench-summary"><span>默认工作区</span><strong>${d.workspace}</strong><span>执行助手</span><strong>${d.assistant}</strong><span>预期交付</span><strong>${d.output}</strong></div><p>演示不连接真实数据。正式产品将沿用现有工作台、Preset 和会话能力。</p><div class="modal-actions">${button('取消','dismiss')}${button('进入任务','start-scenario:'+key,'primary','arrow')}</div>`);return true}
 if(a.startsWith('start-scenario:')){clearTimeout(state.timer);state.busy=false;const key=a.slice(15);const d=scenarioDefinitions[key]||scenarioDefinitions.project;closeModal();state.scenario=key;state.chatTitle=d.title;state.chatPrompt=d.prompt;state.messages=[];state.attachments=[];navigate('chat');return true}
 if(a.startsWith('suggest:')){const input=document.getElementById('generic-input');if(input){input.value=a.slice(8);input.focus()}return true}
 return false;
}
function genericChat(){const d=scenarioDefinitions[state.scenario]||{title:state.chatTitle,assistant:state.activeAgent||'通用办公助手',workspace:'待选择',prompt:state.chatPrompt,output:'根据任务确定'};return `${heading(esc(state.chatTitle),'独立任务上下文 · 保留原有通用会话能力',button('会话历史','history')+button('工作区','workspace','secondary','folder'))}<div class="chat-layout"><section class="chat-main"><div class="chat-head"><div><h3>${d.assistant}</h3><small>选择资料与模型后，在正式应用开始执行</small></div>${badge('交互演示')}</div><div class="chat-transcript"><div class="conversation-welcome"><span class="app-icon">${icon('spark')}</span><h2>${state.scenario==='general'?'今天，有什么工作需要帮忙？':d.title}</h2><p>明确目标，附上资料，把接下来的步骤交给企业助手。</p><button class="suggestion" data-action="suggest:${esc(d.prompt||'整理会议纪要，提取行动项和责任人。')}">${esc(d.prompt||'整理会议纪要，提取行动项和责任人。')} ↗</button></div>${state.messages.map(m=>`<div class="message"><span class="avatar">林</span><div class="message-body"><strong>你</strong><p>${esc(m)}</p><div class="intro-strip">${state.busy?'正在模拟整理任务…':'任务要求已记录。此原型不执行实际推理，不展示未经运行的业务结果。'}</div></div>`).join('')}</div><form id="generic-chat-form" class="composer"><div class="attachment-list">${state.attachments.map(esc).join(' · ')}</div><textarea id="generic-input" aria-label="输入任务" placeholder="描述目标、交付格式与使用的资料…">${state.messages.length?'':esc(state.chatPrompt)}</textarea><div class="composer-tools">${button('附件','attach','chip-button','plus')}${button('PPT 模式','ppt','chip-button','ppt')}${button('模型','model','chip-button')}${button('工具','capabilities','chip-button','plugin')}${button('语音','voice','chip-button')}${state.busy?button('停止','stop','primary send','stop'):'<button type="submit" class="primary send">发送 ↑</button>'}</div></form></section><aside class="inspector"><div class="panel"><div class="panel-head"><h3>本次任务</h3>${icon('folder')}</div><div class="inspector-body"><div class="inspector-row"><span>工作区</span><strong>${d.workspace}</strong></div><div class="inspector-row"><span>预期交付</span><span>${d.output}</span></div><div class="inspector-row"><span>附件</span><span>${state.attachments.length} 份已选择</span></div><p>附件仅显示文件名。任务执行、文件读写和服务连接将在正式客户端中接入。</p></div></div><div class="panel"><div class="panel-head"><h3>交付物</h3></div><div class="empty">尚未生成交付物<br><small>执行结果将在这里预览</small></div></div></aside></div>`}
document.addEventListener('submit',e=>{if(e.target.id!=='generic-chat-form')return;e.preventDefault();const input=document.getElementById('generic-input');const q=input.value.trim();if(!q)return toast('请先描述任务');if(state.busy)return;state.messages.push(q);state.busy=true;render();state.timer=setTimeout(()=>{state.busy=false;if(state.page==='chat')render();toast('演示任务状态已更新，未调用模型')},2000)});
// Round 4: review decisions explicitly describe their scope and remain traceable.
const reviewEvents=[];
function taskAction(a){
 if(a==='approve'){modal('确认交付销售周报',`<p>请核对本次操作范围。原型仅演示状态变更。</p><div class="workbench-summary"><span>操作</span><strong>创建新的报告文件</strong><span>目标位置</span><strong>销售运营 / 交付物</strong><span>文件名称</span><strong>本周销售周报.docx</strong><span>影响范围</span><strong>不覆盖原始资料，不对外发送</strong></div><div class="modal-actions">${button('先看预览','preview')}${button('返回','dismiss')}${button('确认交付（演示）','confirm-approve','primary')}</div>`);return true}
 if(a==='confirm-approve'){state.taskStage='approved';reviewEvents.push({action:'确认交付',reason:'创建周报，不覆盖源文件',time:new Date().toLocaleTimeString('zh-CN')});closeModal();render();toast('已确认演示交付，可在任务中心查看记录');return true}
 if(a==='reject'){modal('退回修改',`<p>说明需要调整的内容，保留本次确认的上下文。</p><form id="reject-form"><label for="reject-reason">修改要求</label><textarea id="reject-reason" name="reason" rows="4" maxlength="300" required placeholder="例如：按区域补充毛利分析，并注明统计口径。"></textarea><div class="modal-actions">${button('取消','dismiss')}<button type="submit" class="primary">退回并记录</button></div></form>`);return true}
 if(a==='approval-history'){modal('审批记录 · 本次演示',reviewEvents.length?reviewEvents.map(r=>`<div class="setting-row"><div><h3>${r.action} · 林晓</h3><p>${esc(r.reason)}</p></div><small>${r.time}</small></div>`).join(''):'<div class="empty">还没有处理记录<br><small>确认或退回销售周报后，记录会出现在这里。</small></div>');return true}
 if(a==='reset-demo'){closeModal();state.knowledgePublished=false;state.taskStage='pending';reviewEvents.length=0;state.messages=[];render();toast('销售周报演示已重置');return true}
 return false;
}
document.addEventListener('submit',e=>{if(e.target.id!=='reject-form')return;e.preventDefault();const reason=new FormData(e.target).get('reason').trim();if(!reason)return toast('请填写修改要求');state.taskStage='rejected';reviewEvents.push({action:'退回修改',reason,time:new Date().toLocaleTimeString('zh-CN')});state.messages.push('修改要求：'+reason);closeModal();render();toast('已记录退回原因，原始资料保持不变')});
// Round 5: source, version, access, and local import status are distinct.
function knowledgeRows(){const q=(state.fileQuery||'').toLowerCase();let list=files.filter(f=>(state.folder==='全部资料'||f[2]===state.folder)&&f[0].toLowerCase().includes(q));if(state.fileSort==='名称')list=[...list].sort((a,b)=>a[0].localeCompare(b[0],'zh-CN'));return list.map(f=>`<tr><td><div class="task-name"><span class="file-icon ${f[1]==='PPTX'?'gold':f[1]==='DOCX'?'blue':''}">${esc(f[1])}</span><div>${esc(f[0])}<small class="file-subtitle">${f[4].includes('仅文件名')?'本地选择 · 未解析':'示例资料 · '+esc(f[2])}</small></div></div></td><td class="muted">${esc(f[3])}</td><td class="muted">${esc(f[4])}</td><td><button class="text-button" data-action="file:${esc(f[0])}">详情 ↗</button></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty">没有找到资料<br><small>试试其他名称或切换分类。</small></div></td></tr>'}
function knowledge(){return `${heading('知识与资料','把散落的文件，变成工作中随时可用的上下文。',button('连接本地文件夹','workspace','secondary','folder')+button('导入资料','attach','primary','upload'))}<div class="intro-strip">${icon('book')}本地文件与共享知识分开管理。共享检索、引用和发布是拟新增能力；原型不解析文件内容。</div><div class="toolbar"><label class="input-wrap">${icon('search')}<input id="file-search" aria-label="搜索资料" placeholder="搜索资料名称" value="${esc(state.fileQuery||'')}"></label><label class="muted">排序 <select id="file-sort" aria-label="资料排序"><option ${state.fileSort!=='名称'?'selected':''}>默认</option><option ${state.fileSort==='名称'?'selected':''}>名称</option></select></label></div><div class="knowledge-layout"><aside class="panel folder-list">${['全部资料','产品资料','销售数据','企业模板','企业制度','导入记录'].map(f=>`<button data-folder="${f}" class="${state.folder===f?'active':''}">${icon('folder')}${f}</button>`).join('')}<div class="news-line">${files.length} 条资料记录</div></aside><div class="panel"><div class="panel-head"><h3>${state.folder}</h3><span>按授权范围访问 · 设计</span></div><table class="table"><thead><tr><th>名称 / 来源</th><th>大小</th><th>最近更新</th><th>操作</th></tr></thead><tbody id="knowledge-rows">${knowledgeRows()}</tbody></table></div></div>`}
function knowledgeAction(a){if(!a.startsWith('file:')&&a!=='knowledge-review')return false;const name=a==='knowledge-review'?'产品手册 2026 · 秋季版':a.slice(5);const f=files.find(x=>x[0]===name);const imported=f?.[4].includes('仅文件名');modal(name,`<div class="detail-badges">${badge(imported?'本地选择':'示例资料')}${badge(imported?'未解析':'拟新增')}</div><div class="workbench-summary"><span>来源</span><strong>${imported?'用户选择的本地文件，仅记录名称':'企业演示数据，非真实文件'}</strong><span>分类</span><strong>${esc(f?.[2]||'产品资料')}</strong><span>访问范围</span><strong>${imported?'当前原型会话':'企业成员（权限设计）'}</strong><span>版本</span><strong>${imported?'尚未建立版本':'V1.2 · 发布前审核'}</strong><span>引用定位</span><strong>${imported?'尚未解析':'产品介绍 / 第 2 节（演示）'}</strong></div><div class="intro-strip">${imported?'没有读取内容、建立索引或上传。正式应用需经过解析与授权流程后才能被 Agent 引用。':'正式回答应附带文件、版本、章节或页码，支持返回原资料核对。引用检索尚未实现。'}</div><div class="modal-actions">${button('关闭','dismiss')}${imported?'':button('模拟确认发布','publish-demo','primary')}</div>`);return true}
document.addEventListener('input',e=>{if(e.target.id==='file-search'){state.fileQuery=e.target.value;document.getElementById('knowledge-rows').innerHTML=knowledgeRows()}});
document.addEventListener('change',e=>{if(e.target.id==='file-sort'){state.fileSort=e.target.value;document.getElementById('knowledge-rows').innerHTML=knowledgeRows()}});
// Round 6: edit and reuse a concrete Agent configuration.
const agentDefinitions=[{name:'销售分析助手',role:'核对统计口径，分析销售数据，输出有依据的经营报告。',skills:'数据分析 / 文档处理',scope:'销售运营',prompt:'先核对时间范围、字段与单位，再分析趋势。缺失数据时明确说明，交付前请用户确认。'},{name:'企业文档助手',role:'使用企业模板与统一语气，起草日常文书。',skills:'文档处理 / 资料检索',scope:'行政协作',prompt:'使用指定模板，不虚构企业信息。涉及对外发布时先交付草稿。'},{name:'通用办公助手',role:'调用授权工具，完成跨文件、多步骤的办公任务。',skills:'办公工具 / 网页搜索',scope:'当前工作区',prompt:'理解任务目标与可用资料，在授权范围内执行并交付可检查的结果。'}];
function agents(){return `${heading('Agent 中心','把企业经验沉淀为可编辑、可复用的岗位助手。',button('导入 .dshpreset','import-preset')+button('创建助手','create-agent','primary','plus'))}<div class="bench-grid full-grid">${agentDefinitions.map((a,i)=>`<article class="bench-card agent-card"><div class="card-top"><span class="avatar">${esc(a.name[0])}</span>${badge(i<3?'企业 Preset':'演示创建')}</div><h3>${esc(a.name)}</h3><p>${esc(a.role)}</p><div class="tags">${a.skills.split(' / ').map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-foot"><button data-action="agent-config:${i}">配置助手 →</button><button data-action="agent-start:${i}">开始会话 ↗</button></div></article>`).join('')}</div><div class="panel settings-panel"><h2>Preset 保持可移植</h2><p>正式产品继续支持 .dshpreset 导入、导出、名称冲突检查和信任提醒。此原型仅导出标明 prototype 的 JSON 示例。</p><div class="setting-row"><div><h3>模型、Skills 与 MCP</h3><p>高级配置回到原有插件与 Preset 管理，不减少底层能力。</p></div>${button('查看全部能力','capabilities')}</div></div>`}
function agentAction(a){if(a.startsWith('agent-config:')){const i=Number(a.slice(13)),g=agentDefinitions[i];if(!g)return true;state.lastAgent=i;modal(g.name+' · 配置',`<p>仅修改本次原型中的助手配置，不影响真实 Preset。</p><form id="agent-config-form" data-index="${i}"><label for="agent-name">助手名称</label><input id="agent-name" name="name" value="${esc(g.name)}" maxlength="24" required><label for="agent-role">职责说明</label><input id="agent-role" name="role" value="${esc(g.role)}" maxlength="100" required><label for="agent-prompt">岗位指令</label><textarea id="agent-prompt" name="prompt" rows="4" required>${esc(g.prompt)}</textarea><div class="workbench-summary"><span>资料范围</span><strong>${esc(g.scope)}</strong><span>工具组合</span><strong>${esc(g.skills)}</strong><span>操作权限</span><strong>关键操作需确认</strong></div><div class="modal-actions">${button('导出配置示例','export-agent')}${button('取消','dismiss')}<button class="primary" type="submit">保存演示配置</button></div></form>`);return true}if(a.startsWith('agent-start:')){clearTimeout(state.timer);state.busy=false;const g=agentDefinitions[Number(a.slice(12))];if(!g)return true;state.scenario='general';state.activeAgent=g.name;state.chatTitle=g.name;state.chatPrompt='';state.messages=[];navigate('chat');return true}if(a==='export-agent'){const g=agentDefinitions[state.lastAgent||0];download('企业助手_原型配置.json',JSON.stringify({prototype:true,...g,note:'不是 dshpreset 包，不能导入真实应用'},null,2),'application/json');return true}return false}
document.addEventListener('submit',e=>{if(e.target.id!=='agent-config-form')return;e.preventDefault();const f=new FormData(e.target);const i=Number(e.target.dataset.index);const name=f.get('name').trim(),role=f.get('role').trim(),prompt=f.get('prompt').trim();if(!name||!role||!prompt)return toast('请完整填写配置');if(agentDefinitions.some((g,n)=>n!==i&&g.name===name))return toast('已存在同名助手，请使用其他名称');Object.assign(agentDefinitions[i],{name,role,prompt});closeModal();render();toast('助手配置已更新，仅在本次原型中生效')});
// Round 7: distinguish requested capability, dependency preparation, and activation.
const marketInstalled=new Set();
const marketItems=[['合同审核工作台','围绕合同资料、审核规则与修改意见组织任务。'],['内容运营工作台','集中选题、素材与内容交付。'],['项目总控台','查看多项目状态、待办与截止日期。']];
function requestPluginToggle(name){if(name==='办公文件处理'&&state.enabled[name]&&state.enabled['模板 PPT']){modal('停用前检查依赖',`<p>模板 PPT 的演示流程使用办公文件能力。请先确认停用范围。</p><div class="intro-strip">本次同时停用“办公文件处理”和“模板 PPT”的演示开关，不会卸载真实插件或删除文件。</div><div class="modal-actions">${button('取消','dismiss')}${button('同时停用（演示）','disable-office','danger')}</div>`);return}if(name==='模板 PPT'&&!state.enabled[name]&&!state.enabled['办公文件处理']){toast('请先启用办公文件处理的演示开关');return}state.enabled[name]=!state.enabled[name];render();toast('已更新演示开关，未改变真实插件')}
function marketBody(){return `<p>以下为社区工作台入口示例。正式产品沿用原市场，实际安装前需要检查版本、权限与来源。</p>${marketItems.map((m,i)=>`<div class="setting-row"><div><h3>${m[0]}</h3><p>${m[1]}</p><small>社区扩展 · 此处不下载代码</small></div>${button(marketInstalled.has(i)?'移除演示':'查看安装','market-item:'+i)}</div>`).join('')}<div class="modal-actions">${button('关闭','dismiss','primary')}</div>`}
function pluginAction(a){if(a==='disable-office'){state.enabled['办公文件处理']=false;state.enabled['模板 PPT']=false;closeModal();render();toast('两项演示开关已关闭');return true}if(a==='market'){modal('工作台与插件市场',marketBody());return true}if(a.startsWith('market-item:')){const i=Number(a.slice(12));if(!marketItems[i])return true;if(marketInstalled.has(i)){marketInstalled.delete(i);modal('工作台与插件市场',marketBody());toast('已移除演示安装记录');return true}modal('安装前检查 · '+marketItems[i][0],`<div class="workbench-summary"><span>来源</span><strong>社区市场示例</strong><span>访问范围</span><strong>所选工作区资料</strong><span>依赖能力</span><strong>通用会话、文档工具</strong><span>版本检查</span><strong>正式安装前验证宿主兼容性</strong></div><p>扩展可能执行工具。正式应用需展示可信来源、权限和版本；此处不会联网、下载或执行代码。</p><div class="modal-actions">${button('返回市场','market')}${button('模拟安装','market-install:'+i,'primary')}</div>`);return true}if(a.startsWith('market-install:')){marketInstalled.add(Number(a.slice(15)));modal('工作台与插件市场',marketBody());toast('已添加演示安装记录，未安装实际插件');return true}if(a.startsWith('plugin:')){const name=a.slice(7);modal(name+' · 配置',`<p>沿用原有插件配置页，并增加清楚的使用范围。这里的参数仅用于演示。</p><form id="plugin-config-form" data-name="${esc(name)}"><label for="plugin-scope">可用范围</label><select id="plugin-scope" name="scope"><option ${state.pluginSettings?.[name]?.scope!=='所有授权工作区'?'selected':''}>仅当前工作区</option><option ${state.pluginSettings?.[name]?.scope==='所有授权工作区'?'selected':''}>所有授权工作区</option></select><label for="plugin-confirm">操作确认</label><select id="plugin-confirm" name="approval"><option ${state.pluginSettings?.[name]?.approval!=='只读操作自动通过'?'selected':''}>关键操作逐次确认</option><option ${state.pluginSettings?.[name]?.approval==='只读操作自动通过'?'selected':''}>只读操作自动通过</option></select><div class="intro-strip" style="margin-top:18px">当前状态：${state.enabled[name]?'演示开关已开启':'演示开关已关闭'}。配置、安装、运行依赖和实际激活是不同状态。</div><div class="modal-actions">${button('取消','dismiss')}<button type="submit" class="primary">保存演示参数</button></div></form>`);return true}return false}
document.addEventListener('submit',e=>{if(e.target.id!=='plugin-config-form')return;e.preventDefault();const f=new FormData(e.target);state.pluginSettings??={};state.pluginSettings[e.target.dataset.name]={scope:f.get('scope'),approval:f.get('approval')};closeModal();toast('已保存本次演示配置，未影响真实插件')});
// Round 8: enterprise roles and policy proposals are reviewable, not implicit security promises.
function enterpriseAction(a){if(a==='permissions'||a.startsWith('role:')){modal('企业角色权限矩阵 · 设计',`<p>拟新增能力。实际权限必须由服务端或受信任宿主校验，不能依靠前端显隐。</p><table class="table"><thead><tr><th>操作</th><th>管理员</th><th>负责人</th><th>成员</th></tr></thead><tbody>${[['组织与品牌','管理','查看','查看'],['工作台与模板','全企业','本部门','使用'],['企业资料','授权管理','部门管理','授权读取'],['插件与服务','策略管理','申请','使用'],['任务与交付','按授权','按授权','按授权'],['审计记录','按角色授权','本部门','本人']].map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')}</tbody></table><div class="modal-actions">${button('知道了','dismiss','primary')}</div>`);return true}if(a==='invite'){modal('创建成员邀请草稿',`<p>只保存本次原型中的草稿，不发送邮件、不创建真实账号。</p><form id="invite-form"><label for="invite-name">成员姓名</label><input id="invite-name" name="name" placeholder="输入演示成员姓名" maxlength="20" required><label for="invite-role">拟分配角色</label><select id="invite-role" name="role"><option>成员</option><option>业务负责人</option><option>管理员</option></select><label for="invite-dept">所属部门</label><select id="invite-dept" name="dept"><option>销售运营</option><option>品牌与市场</option><option>行政与人事</option></select><div class="modal-actions">${button('取消','dismiss')}<button class="primary" type="submit">保存邀请草稿</button></div></form>`);return true}if(a==='policy'){modal('关键操作策略 · 演示设置',`<p>保留原有工具权限，在企业层增加可解释的策略。此表单只影响原型说明。</p><form id="policy-form"><div class="setting-row"><div><h3>覆盖已有文件</h3><p>显示目标、影响范围并逐次确认</p></div>${badge('需确认')}</div><div class="setting-row"><div><h3>写入 ERP / CRM</h3><p>业务规则校验通过后才允许提交</p></div>${badge('需确认')}</div><label for="external-policy">对外发送消息或文件</label><select name="external" id="external-policy"><option value="confirm" ${state.externalPolicy!=='deny'?'selected':''}>发送前确认</option><option value="deny" ${state.externalPolicy==='deny'?'selected':''}>禁止对外发送</option></select><div class="modal-actions">${button('取消','dismiss')}<button type="submit" class="primary">保存演示策略</button></div></form>`);return true}if(a==='audit'){modal('操作审计 · 演示记录',`<p>以下来自本次原型交互，不是服务器审计日志。</p>${reviewEvents.length?reviewEvents.map(r=>`<div class="setting-row"><div><h3>林晓 · ${r.action}</h3><p>${esc(r.reason)}</p></div><small>${r.time}</small></div>`).join(''):'<div class="empty">暂无确认记录，请先处理销售周报任务。</div>'}<p style="margin-top:20px">正式审计需要补充任务 ID、工具参数摘要、权限决定、时间、结果及失败原因，并明确脱敏和保留周期。</p>`);return true}return false}
document.addEventListener('submit',e=>{if(e.target.id==='invite-form'){e.preventDefault();const f=new FormData(e.target);const name=f.get('name').trim();if(!name)return toast('请填写成员姓名');state.memberDrafts??=[];state.memberDrafts.push({name,role:f.get('role'),dept:f.get('dept')});closeModal();render();toast('已保存邀请草稿，没有发送邀请')}if(e.target.id==='policy-form'){e.preventDefault();state.externalPolicy=new FormData(e.target).get('external');closeModal();render();toast('演示策略已保存，真实权限未改变')}});
// Round 9: desktop features have complete, explicitly simulated flows.
function desktopAction(a){if(a==='theme'){modal('显示偏好',`<p>原型提供浅色与深色预览。正式应用继续保留原有主题和缩放能力。</p><div class="theme-options">${button('浅色 · 远山绿','theme:light','secondary')}${button('深色 · 森林夜','theme:dark','secondary')}</div><div class="setting-row"><div><h3>布局密度</h3><p>标准 / 紧凑</p></div>${button('切换密度','maximize')}</div>`);return true}if(a.startsWith('theme:')){document.body.classList.toggle('dark',a==='theme:dark');state.theme=a.slice(6);toast('已切换原型主题');return true}if(a==='phone'){modal('手机连接 · 原型演示',`<div class="pairing-visual">${icon('phone')}<strong>${state.phoneDemo?'演示设备已配对':'准备连接手机'}</strong><small>不生成二维码，不打开网络端口</small></div><p>正式流程：选择局域网或临时公网 → 手机扫描短时二维码 → 确认配对 → 继续会话 → 随时断开。</p><div class="workbench-summary"><span>连接范围</span><strong>局域网（演示）</strong><span>配对凭据</span><strong>正式应用使用短时 Token</strong><span>企业策略</span><strong>可禁用临时公网连接</strong></div><div class="modal-actions">${button('关闭','dismiss')}${button(state.phoneDemo?'断开演示连接':'模拟完成配对',state.phoneDemo?'phone-disconnect':'phone-pair','primary')}</div>`);return true}if(a==='phone-pair'||a==='phone-disconnect'){state.phoneDemo=a==='phone-pair';desktopAction('phone');return true}if(a==='system:safe'){modal('安全模式 · 恢复流程',`<p>正式安全模式临时屏蔽第三方插件，保留基础会话、模型配置、工作区及恢复入口。</p><div class="workflow-steps"><div><span>1</span><strong>进入隔离 Profile</strong></div><div><span>2</span><strong>检查问题插件</strong></div><div><span>3</span><strong>恢复正常启动</strong></div></div><div class="modal-actions">${button('取消','dismiss')}${button('预览安全模式状态','safe-enter','primary')}</div>`);return true}if(a==='safe-enter'||a==='safe-exit'){state.safeDemo=a==='safe-enter';closeModal();render();return true}if(a==='system:logs'){modal('运行日志 · 演示示例',`<pre class="log-preview">[demo] desktop shell mounted\n[demo] enterprise navigation ready\n[demo] model service: not connected\n[demo] real runtime: not started\n[demo] no credentials collected</pre><p>真实应用日志应保留错误原因与阶段，并排除密钥、Token 和敏感正文。</p><div class="modal-actions">${button('导出示例日志','download-log','primary')}</div>`);return true}if(a==='download-log'){download('桌面诊断_原型演示.txt','这是原型示例，不是实际应用日志。\n界面：可预览\n模型：未连接\n运行时：未启动\n凭据：未收集');return true}if(a==='system:updates'){modal('应用更新 · 流程预览',`<p>原型未查询版本，也不会下载或安装更新。正式应用由用户决定下载和重启。</p><div class="workflow-steps"><div><span>1</span><strong>发现新版本</strong></div><div><span>2</span><strong>确认后下载</strong></div><div><span>3</span><strong>重启并安装</strong></div></div><div class="modal-actions">${button('跳过演示版本','dismiss')}${button('预览安装确认','update-confirm','primary')}</div>`);return true}if(a==='update-confirm'){info('安装确认状态 · 演示','正式安装前应提示保存当前工作，说明会话与配置的保留策略。此原型不会关闭窗口或执行安装。');return true}return false}
